/** Live-map zones (0053). */
export type MapZoneKind =
  | 'cordon' | 'exclusion' | 'evacuation' | 'hazard' | 'search'
  | 'road_closure' | 'route' | 'staging' | 'command_post' | 'rendezvous'
  | 'last_seen' | 'note';
export type MapZoneShape = 'polygon' | 'circle' | 'line' | 'point';
export type MapZoneVisibility = 'private' | 'department' | 'departments' | 'incident' | 'everyone';

/** Bodycams (0054). */
export type BodycamStatus = 'Available' | 'Booked out' | 'In repair' | 'Lost' | 'Retired';
export type BodycamViewReason = 'incident' | 'officer_safety' | 'sos' | 'supervision' | 'investigation' | 'other';

/** The notice a fine is served on (migration 0057). */
export type FineNoticeType = 'AARTO 01' | 'Section 56' | 'Section 341';

export type Silo = 'Ethekwini' | 'MetroPolice' | 'MetroFire' | 'Medical' | 'EthekwiniDisaster';

/**
 * The duty office screens (0085), by eThekwini's Oracle program codes: staff,
 * call signs, sections, endorsements, absence codes, duty allocation, duty
 * maintenance, duties for operation (the parade sheet) and leave.
 */
export type ModuleCode = 'STFM' | 'CSNM' | 'SECM' | 'ENTM' | 'ABSM' | 'DUTA' | 'DUTM' | 'DUTR' | 'LEAM';
/** Oracle's Enquiry / Update. */
export type ModuleLevel = 'View' | 'Edit';
/**
 * One department's part of a call (0073): waiting at its desk, dispatched,
 * its lead's progress, then finished by its report, stood down, or cancelled
 * with the call.
 */
export type DepartmentPartStatus =
  | 'Waiting' | 'Dispatched' | 'En Route' | 'Arrived' | 'On Scene' | 'Transporting'
  | 'Resolved' | 'Not needed' | 'Cancelled';
/** Why someone senior recorded a shift the way they did (0072). */
export type ShiftOutcome = 'Present' | 'Excused' | 'Sick' | 'Absent without leave' | 'Swapped';

export type UserRole =
  | 'SystemAdmin' | 'SuperAdmin' | 'Admin' | 'Supervisor'
  | 'Dispatcher' | 'Operator' | 'ControlRoom' | 'IncidentLogger' | 'Viewer' | 'System'
  | 'Captain' | 'Police' | 'Officer' | 'Metro' | 'Security'
  | 'Chief' | 'FireChief' | 'Firefighter'
  | 'Paramedic' | 'Doctor'
  | 'Disaster' | 'CaseManager' | 'Citizen'
  | 'Responder' | 'Staff' | 'SystemController';

export type IncidentStatus =
  | 'New' | 'Pending' | 'Pending Dispatch' | 'Pending Analysis'
  | 'Dispatched' | 'En Route' | 'Arrived' | 'On Scene' | 'Transporting' | 'Active'
  | 'Closed' | 'Resolved';

export type IncidentSeverity = 'Low' | 'Medium' | 'High' | 'Critical';

/** Why an alert was raised — drives its icon and grouping. */
export type AlertKind =
  | 'assignment' | 'incident_new' | 'incident_update' | 'broadcast' | 'system' | 'info'
  // Police response (migrations 0039/0040): an open dispatch to on-duty
  // officers, and the call being accepted / resolved, told to command.
  | 'dispatch' | 'accepted' | 'resolved'
  // Assign / backup (0042) and an officer's SOS to dispatch and command (0043).
  | 'responding' | 'reassigned' | 'backup' | 'sos'
  // Schedules (0072): about a person's own shifts and leave, and to those who
  // oversee them. The server pushes the ones in schedule_push_kinds().
  | 'shift_published' | 'shift_changed' | 'shift_confirm' | 'shift_late' | 'shift_noshow'
  | 'shift_team_late' | 'shift_team_noshow' | 'shift_started_late' | 'shift_outcome'
  | 'leave_request' | 'leave_decision' | 'swap' | 'swap_waiting'
  // Departments' parts of a call (0073): one department's report filed while
  // others still work it; a department stood down, and its crew told.
  | 'report_filed' | 'stood_down' | 'stand_down'
  // An officer closed their department's part on scene (0074).
  | 'officer_closed'
  // Sent by a person (0084): a note, a mail, a task.
  | 'mail' | 'task';

/** Whom a notification is for (0084). */
export type AlertAudience = 'person' | 'people' | 'role' | 'department' | 'organisation';

/** How forcefully an alert interrupts: a corner toast or a modal that blocks. */
export type AlertPresentation = 'toast' | 'modal';

export type ApparatusStatus =
  | 'Available' | 'In Use' | 'En Route' | 'On Scene'
  | 'Out of Service' | 'Maintenance' | 'Decommissioned';

